mapper.select:
SELECT ui.ingredient_id, ui.user_id, ui.master_ingredient_id, ui.category_id, ui.name, ui.storage_type, ui.quantity, ui.unit, ui.expire_date, (ui.expire_date - (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date) AS d_day, ui.memo, ui.status, ui.created_at, ui.updated_at FROM public.user_ingredient ui WHERE ui.user_id = #{userId} AND ui.status = COALESCE(#{status}, 'ACTIVE')
AND (ui.name ILIKE CONCAT('%', #{query}, '%') OR ui.memo ILIKE CONCAT('%', #{query}, '%'))
AND ui.category_id = #{categoryId}
AND ui.storage_type = #{storageType}
ORDER BY ui.expire_date ASC, ui.created_at ASC

SELECT COALESCE(SUM(ui.quantity), 0)
FROM public.user_ingredient ui
WHERE ui.user_id = #{userId}
  AND ui.master_ingredient_id = #{masterIngredientId}
  AND ui.status = 'ACTIVE'
